---Собрать плоский список записей справки
---@param opts? Help.Opts
---@return Help.Entry[]
function M.entries(opts)
   opts = opts or {}
   local bindings = require('config.bindings')

   local active_keys = opts.keys or bindings.keys or {}
   local active_tables = opts.key_tables or bindings.key_tables or {}
   local active_mouse = opts.mouse_bindings or bindings.mouse_bindings or {}
   local leader = opts.leader or bindings.leader
   local defaults_off = opts.defaults_disabled
   if defaults_off == nil then
      defaults_off = bindings.disable_default_key_bindings == true
   end

   local leader_chord = nil
   if leader ~= nil then
      local mods = mods_list(normalize_mods(leader.mods))
      if #mods == 0 then
         leader_chord = tostring(leader.key)
      else
         leader_chord = table.concat(mods, '+') .. '+' .. tostring(leader.key)
      end
   end

   local entries = {}

   ---@param command table
   ---@param mods string
   ---@param key any
   ---@param source Help.Source
   ---@param signature string|nil
   ---@param section string|nil
   local function push_key(command, mods, key, source, signature, section)
      local base, prefix = split_key(key)
      local norm = normalize_mods(mods)
      local label_mods = #mods_list(norm) > 0 and table.concat(mods_list(norm), '+') or ''
      local key_part = key_label(base, prefix)
      local chord
      if section ~= nil then
         chord = #label_mods > 0 and string.format('%s+%s', label_mods, key_part) or key_part
      elseif leader_chord ~= nil and norm:find('LEADER') then
         chord = string.format('%s, %s', leader_chord, key_part)
      elseif #label_mods > 0 then
         chord = string.format('%s+%s', label_mods, key_part)
      else
         chord = key_part
      end
      table.insert(entries, {
         category = section ~= nil and 'Клавиатурные таблицы' or category_of(command),
         label = section ~= nil and string.format('  %s', chord) or chord,
         chord = chord,
         description = describe_action(command),
         source = source,
         active = true,
         origin = 'custom',
         signature = signature,
         section = section,
      })
   end

   -- активные сочетания из конфига / effective_config
   local active_signatures = {}
   for _, binding in ipairs(active_keys) do
      local mods = normalize_mods(binding.mods)
      local base = split_key(binding.key)
      local signature = mods .. '|' .. base
      active_signatures[signature] = action_signature(binding.action)
      push_key(binding, mods, base, 'config', signature)
   end

   -- стандартные сочетания wezterm
   local defaults = default_keys()
   local inactive = {}
   if defaults ~= nil then
      for _, binding in ipairs(defaults) do
         local mods = normalize_mods(binding.mods)
         local base = split_key(binding.key)
         local signature = mods .. '|' .. base
         local current = active_signatures[signature]
         if current == nil then
            table.insert(inactive, {
               category = category_of(binding),
               label = nil,
               chord = nil,
               description = describe_action(binding),
               source = 'default',
               active = false,
               origin = 'standard',
               mods = mods,
               key = base,
               key_prefix = split_key(binding.key),
               section = nil,
            })
         elseif current ~= action_signature(binding.action) then
            for _, entry in ipairs(entries) do
               if entry.signature == signature then
                  entry.origin = 'override'
                  entry.description = entry.description
                     .. string.format('  [изменено, было: %s]', describe_action(binding))
               end
            end
         end
      end
   end

   -- мышиные привязки
   local default_mouse_signatures = {}
   for _, binding in ipairs(MOUSE_DEFAULTS) do
      default_mouse_signatures[mouse_signature(binding)] = action_signature(binding.action)
   end
   local mouse_source = {}
   if opts.mouse_bindings ~= nil then
      mouse_source = active_mouse
   else
      mouse_source = vim_list_extend(MOUSE_DEFAULTS, active_mouse)
   end
   for _, binding in ipairs(mouse_source) do
      local signature = mouse_signature(binding)
      local is_default = default_mouse_signatures[signature] ~= nil
      table.insert(entries, {
         category = 'Мышь',
         label = event_label(normalize_mods(binding.mods), binding.event),
         chord = event_label(normalize_mods(binding.mods), binding.event),
         description = describe_action(binding),
         source = (is_default and opts.mouse_bindings ~= nil) and 'default' or 'config',
         active = true,
         origin = (is_default and opts.mouse_bindings ~= nil) and 'standard'
            or (is_default and 'override' or 'custom'),
         signature = signature,
         section = nil,
      })
   end

   -- клавиатурные таблицы
   local tables = {}
   for name, rows in pairs(active_tables) do
      tables[name] = { source = 'config', rows = rows }
   end
   local def_tables = default_key_tables()
   if def_tables ~= nil then
      for name, rows in pairs(def_tables) do
         if tables[name] == nil then
            tables[name] = { source = 'default', rows = rows }
         end
      end
   end

   local table_names = {}
   for name in pairs(tables) do
      table.insert(table_names, name)
   end
   table.sort(table_names)

   for _, name in ipairs(table_names) do
      local table_info = tables[name]
      for _, row in ipairs(table_info.rows) do
         push_key(row, row.mods or 'NONE', row.key, table_info.source, name .. '|' .. tostring(row.key), name)
      end
   end

   for _, entry in ipairs(entries) do
      entry.rank = CATEGORY_RANK[entry.category:lower()] or #CATEGORY_ORDER + 1
   end

   -- добавляем неактивные стандартные сочетания в общий список
   for _, entry in ipairs(inactive) do
      table.insert(entries, entry)
   end

   return entries, {
      leader = leader_chord,
      defaults_off = defaults_off,
      defaults_available = defaults ~= nil,
   }
end

---Склеить два списка (без изменения исходных)
---@param a table[]
---@param b table[]
---@return table[]
local function vim_list_extend(a, b)
   local result = {}
   for _, v in ipairs(a) do
      table.insert(result, v)
   end
   for _, v in ipairs(b) do
      table.insert(result, v)
   end
   return result
end

