---@param str string
---@param count number
---@return string
local function srep(str, count)
   local result = ''
   for _ = 1, count do
      result = result .. str
   end
   return result
end

---@param str string
---@param count number
---@param symbol string
---@return string
local function cpad(str, count, symbol)
   local l = #str
   if l >= count or #symbol ~= 1 then
      return str
   end
   local left = math.floor((count - l) / 2)
   return srep(symbol, left) .. str .. srep(symbol, count - l - left)
end

---@param mods string
---@param prefix string|nil
---@return Help.Entry
local function inactive_entry(mods, prefix)
   local norm = normalize_mods(mods)
   local base = split_key(prefix)
   local parts = mods_list(norm)
   return {
      label = #parts > 0 and table.concat(parts, '+') .. '+' .. base or base,
      mods = norm,
      key = base,
   }
end

---@param value any
---@return string
local function format_time(value)
   if type(value) == 'table' and type(value.year) == 'number' then
      return string.format(
         '%04d-%02d-%02d %02d:%02d:%02d',
         value.year,
         value.month,
         value.day,
         value.hour,
         value.min,
         value.sec
      )
   end
   return tostring(value)
end

---Отрендерить справку в текст
---@param opts? Help.Opts
---@return string
function M.render(opts)
   opts = opts or {}
   local entries, meta = M.entries(opts)
   local leader = meta.leader
   local defaults_off = meta.defaults_off

   local width = 16
   for _, entry in ipairs(entries) do
      width = math.max(width, #entry.label)
   end
   width = math.min(width, 40)

   local out = {}
   local function add(line)
      table.insert(out, line)
   end

   add(cpad(' WezTerm — горячие клавиши ', 100, '='))
   add(string.format(' wezterm %s   ОС: %s', wezterm.version or '?', platform.os))
   add(string.format(' конфиг: %s', wezterm.config_file or '?'))
   add(string.format(' создано: %s', format_time(wezterm.time.now())))
   if opts.from_effective == true then
      add(' источник: window:effective_config() (фактические данные текущего окна)')
   else
      add(' источник: config/bindings.lua + wezterm.gui.default_keys()')
   end
   add('')
   add(' Легенда:')
   add('   *   сочетание из конфига (активно)')
   add('   →   стандартное сочетание, перекрыто конфигом')
   add('   -   стандартное сочетание wezterm')
   if defaults_off then
      add('       в основной таблице «-» означает «НЕ АКТИВНО» (disable_default_key_bindings = true);')
      add('       в клавиатурных таблицах и мыши стандартные сочетания по-прежнему активны')
   end
   add('   (физ.) — по физической позиции клавиши, независимо от раскладки')
   if leader then
      add(string.format('   лидер: %s', leader))
   end
   add(string.format('   вызов справки: %s — полный список, %s — поиск', 'F1', 'CTRL+Space ?'))
   add('')

   local function render_entry(entry)
      if entry.active == false then
         local label = entry.label
            or inactive_entry(entry.mods, (entry.key_prefix or entry.key))
               .label
         if #label + 2 > width then
            width = #label + 2
         end
      else
         label = entry.label
      end
      local marker = entry.active and ' *' or ' -'
      if entry.origin == 'override' then
         marker = entry.active and ' →' or ' -'
      end
      return string.format(' %s %-*s  %s', marker, width, label, entry.description)
   end

   -- основная таблица + мышь + таблицы клавиатур
   local ordered = {}
   for _, entry in ipairs(entries) do
      table.insert(ordered, entry)
   end
   table.sort(ordered, function(a, b)
      if a.rank ~= b.rank then
         return a.rank < b.rank
      end
      if a.active ~= b.active then
         return a.active
      end
      if a.section ~= b.section then
         return (a.section or '') < (b.section or '')
      end
      if a.label ~= b.label then
         return a.label < b.label
      end
      return a.description < b.description
   end)

   local current_section = nil
   local printed_category = nil
   local buffered = {}
   local function flush()
      if #buffered == 0 then
         return
      end
      if current_section ~= nil then
         table.insert(buffered, 2, string.format('   [%s]', current_section))
      end
      for _, line in ipairs(buffered) do
         add(line)
      end
      buffered = {}
   end

   for _, entry in ipairs(ordered) do
      if entry.category ~= printed_category then
         flush()
         printed_category = entry.category
         add('')
         add(cpad(' ' .. printed_category .. ' ', 100, '-'))
         current_section = nil
      end
      if entry.section ~= current_section then
         flush()
         current_section = entry.section
         buffered = {}
         table.insert(buffered, render_entry(entry))
      else
         table.insert(buffered, render_entry(entry))
      end
   end
   flush()

   add('')
   add(cpad(' Дополнительно ', 100, '-'))
   add('   CTRL+SHIFT+P — командная панель (все стандартные команды wezterm)')
   add('   CTRL+F4 / CTRL+F5 — лаунчер по вкладкам / рабочим пространствам')
   add('   F12 — отладочный оверлей, там же _keys() печатает эту справку')
   add('')

   return table.concat(out, '\n')
end

---Записи для fuzzy-поиска (только активные сочетания основной таблицы)
---@param opts? Help.Opts
---@return Help.Entry[]
function M.active_entries(opts)
   local entries = M.entries(opts)
   local result = {}
   for _, entry in ipairs(entries) do
      if entry.active and entry.section == nil and entry.category ~= 'Мышь' then
         table.insert(result, entry)
      end
   end
   return result
end

