---Склеить два списка, не меняя исходные
---@param a table[]
---@param b table[]
---@return table[]
local function list_extend(a, b)
   local result = {}
   for _, v in ipairs(a) do
      table.insert(result, v)
   end
   for _, v in ipairs(b) do
      table.insert(result, v)
   end
   return result
end

---@param str string
---@param count number
---@return string
local function srep(str, count)
   local result = ''
   for _ = 1, count do
      result = result .. str
   end
   return result
end

---@param str string
---@param count number
---@param symbol string
---@return string
local function cpad(str, count, symbol)
   local l = #str
   if l >= count or #symbol ~= 1 then
      return str
   end
   local left = math.floor((count - l) / 2)
   return srep(symbol, left) .. str .. srep(symbol, count - l - left)
end

